registerPy("sched", () => "\"\"\"A generally useful event scheduler class.\n\nEach instance of this class manages its own queue.\nNo multi-threading is implied; you are supposed to hack that\nyourself, or use a single instance per application.\n\nEach instance is parametrized with two functions, one that is\nsupposed to return the current time, one that is supposed to\nimplement a delay.  You can implement real-time scheduling by\nsubstituting time and sleep from built-in module time, or you can\nimplement simulated time by writing your own functions.  This can\nalso be used to integrate scheduling with STDWIN events; the delay\nfunction is allowed to modify the queue.  Time can be expressed as\nintegers or floating-point numbers, as long as it is consistent.\n\nEvents are specified by tuples (time, priority, action, argument, kwargs).\nAs in UNIX, lower priority numbers mean higher priority; in this\nway the queue can be maintained as a priority queue.  Execution of the\nevent means calling the action function, passing it the argument\nsequence in \"argument\" (remember that in Python, multiple function\narguments are be packed in a sequence) and keyword parameters in \"kwargs\".\nThe action function may be an instance method so it\nhas another way to reference private data (besides global variables).\n\"\"\"\nimport time\nimport heapq\nfrom collections import namedtuple\nfrom itertools import count\nimport threading\nfrom time import monotonic as _time\n__all__ = [\"scheduler\"]\nEvent = namedtuple('Event', 'time, priority, sequence, action, argument, kwargs')\nEvent.time.__doc__ = ('''Numeric type compatible with the return value of the\ntimefunc function passed to the constructor.''')\nEvent.priority.__doc__ = ('''Events scheduled for the same time will be executed\nin the order of their priority.''')\nEvent.sequence.__doc__ = ('''A continually increasing sequence number that\n    separates events if time and priority are equal.''')\nEvent.action.__doc__ = ('''Executing the event means executing\naction(*argument, **kwargs)''')\nEvent.argument.__doc__ = ('''argument is a sequence holding the positional\narguments for the action.''')\nEvent.kwargs.__doc__ = ('''kwargs is a dictionary holding the keyword\narguments for the action.''')\n_sentinel = object()\nclass scheduler:\n    def __init__(self, timefunc=_time, delayfunc=time.sleep):\n        \"\"\"Initialize a new instance, passing the time and delay\n        functions\"\"\"\n        self._queue = []\n        self._lock = threading.RLock()\n        self.timefunc = timefunc\n        self.delayfunc = delayfunc\n        self._sequence_generator = count()\n    def enterabs(self, time, priority, action, argument=(), kwargs=_sentinel):\n        \"\"\"Enter a new event in the queue at an absolute time.\n\n        Returns an ID for the event which can be used to remove it,\n        if necessary.\n\n        \"\"\"\n        if kwargs is _sentinel:\n            kwargs = {}\n        with self._lock:\n            event = Event(time, priority, next(self._sequence_generator),\n                          action, argument, kwargs)\n            heapq.heappush(self._queue, event)\n        return event # The ID\n    def enter(self, delay, priority, action, argument=(), kwargs=_sentinel):\n        \"\"\"A variant that specifies the time as a relative time.\n\n        This is actually the more commonly used interface.\n\n        \"\"\"\n        time = self.timefunc() + delay\n        return self.enterabs(time, priority, action, argument, kwargs)\n    def cancel(self, event):\n        \"\"\"Remove an event from the queue.\n\n        This must be presented the ID as returned by enter().\n        If the event is not in the queue, this raises ValueError.\n\n        \"\"\"\n        with self._lock:\n            self._queue.remove(event)\n            heapq.heapify(self._queue)\n    def empty(self):\n        \"\"\"Check whether the queue is empty.\"\"\"\n        with self._lock:\n            return not self._queue\n    def run(self, blocking=True):\n        \"\"\"Execute events until the queue is empty.\n        If blocking is False executes the scheduled events due to\n        expire soonest (if any) and then return the deadline of the\n        next scheduled call in the scheduler.\n\n        When there is a positive delay until the first event, the\n        delay function is called and the event is left in the queue;\n        otherwise, the event is removed from the queue and executed\n        (its action function is called, passing it the argument).  If\n        the delay function returns prematurely, it is simply\n        restarted.\n\n        It is legal for both the delay function and the action\n        function to modify the queue or to raise an exception;\n        exceptions are not caught but the scheduler's state remains\n        well-defined so run() may be called again.\n\n        A questionable hack is added to allow other threads to run:\n        just after an event is executed, a delay of 0 is executed, to\n        avoid monopolizing the CPU when other threads are also\n        runnable.\n\n        \"\"\"\n        lock = self._lock\n        q = self._queue\n        delayfunc = self.delayfunc\n        timefunc = self.timefunc\n        pop = heapq.heappop\n        while True:\n            with lock:\n                if not q:\n                    break\n                (time, priority, sequence, action,\n                 argument, kwargs) = q[0]\n                now = timefunc()\n                if time > now:\n                    delay = True\n                else:\n                    delay = False\n                    pop(q)\n            if delay:\n                if not blocking:\n                    return time - now\n                delayfunc(time - now)\n            else:\n                action(*argument, **kwargs)\n                delayfunc(0)   # Let other threads run\n    @property\n    def queue(self):\n        \"\"\"An ordered list of upcoming events.\n\n        Events are named tuples with fields for:\n            time, priority, action, arguments, kwargs\n\n        \"\"\"\n        with self._lock:\n            events = self._queue[:]\n        return list(map(heapq.heappop, [events]*len(events)))\n", false);
registerPy("dis", () => "\"\"\"dis (m\u00ednimo): solo lo que necesita inspect.\"\"\"\nCOMPILER_FLAG_NAMES = {\n    1: \"OPTIMIZED\", 2: \"NEWLOCALS\", 4: \"VARARGS\", 8: \"VARKEYWORDS\", 16: \"NESTED\", 32: \"GENERATOR\", 64: \"NOFREE\",\n    128: \"COROUTINE\", 256: \"ITERABLE_COROUTINE\", 512: \"ASYNC_GENERATOR\",\n}\ndef dis(*args, **kwargs):\n    raise NotImplementedError(\"dis no est\u00e1 disponible: este int\u00e9rprete no usa bytecode\")\ndef show_code(*args, **kwargs):\n    dis()\ndef get_instructions(*args, **kwargs):\n    dis()\n", false);
